function [ys_, params, info] = steadystate(ys_, exo_, params)
% Steady state generated by Dynare preprocessor
    info = 0;
    v_tau_ss_v=params(1)*params(15)*params(60)/(1-params(1)*(1-params(60)));
    q_ss_v=1-params(44)-params(15)*params(56)-v_tau_ss_v*(1-params(56));
    rk_ss_v=q_ss_v*(1/params(1)-1+params(2))/(1-params(15));
    sharei_v=params(2)*params(3)/rk_ss_v;
    sharec_v=1-params(19)-sharei_v*(1-params(61));
    aac_v=1-params(11);
    aag_v=1-params(13);
    bbc_v=params(1)*params(11)*(params(12)-1)/(params(1)*params(12)-1)-1;
    bbg_v=params(1)*params(13)*(params(14)-1)/(params(1)*params(14)-1)-1;
    mc_ss_v=1+1/(params(4)*(sharec_v*aac_v/bbc_v+params(19)*aag_v/bbg_v-sharei_v*(1-params(61))));
    K_ss_v=(rk_ss_v/(params(3)*mc_ss_v))^(1/(params(3)-1))*params(18);
    w_ss_v=mc_ss_v*(1-params(3))*(K_ss_v/params(18))^params(3);
    Y_ss_v=(params(18)*w_ss_v+rk_ss_v*K_ss_v)/(1-params(61));
    I_ss_v=params(2)*K_ss_v;
    G_ss_v=params(19)*Y_ss_v;
    C_ss_v=Y_ss_v-I_ss_v-G_ss_v;
    k_tau_ss_v=(1-params(56))*I_ss_v/params(60);
    R_ss_v=1+(params(17)/params(1)-1)/(1-params(48));
    b_ss_v=Y_ss_v*params(20);
    div_ss_v=params(61)*Y_ss_v;
    taxrev_ss_v=C_ss_v*params(40)+params(18)*w_ss_v*params(16)+params(15)*(rk_ss_v*K_ss_v-params(60)*k_tau_ss_v-params(56)*I_ss_v)+b_ss_v*params(48)*(R_ss_v-1)/params(17)+div_ss_v*params(52)-params(44)*I_ss_v;
    tr_ss_v=taxrev_ss_v+b_ss_v*(1-R_ss_v/params(17))-G_ss_v;
    xc_ss_v=(1-params(11))*C_ss_v;
    xg_ss_v=(1-params(13))*G_ss_v;
    wtilde_ss_v=params(5)/((params(5)-1)*(1-params(16)));
    a_share_v=xc_ss_v*(1+params(40))/(xc_ss_v*(1+params(40))+w_ss_v/wtilde_ss_v*(1-params(18)));
    lambda_ss_v=a_share_v*(xc_ss_v^a_share_v*(1-params(18))^(1-a_share_v))^(1-params(6))/(xc_ss_v*(1+params(40)));
    ys_(36)=1;
    ys_(37)=1;
    ys_(38)=1;
    ys_(1)=C_ss_v;
    ys_(2)=G_ss_v;
    ys_(3)=I_ss_v;
    ys_(4)=K_ss_v;
    ys_(5)=1;
    ys_(6)=params(18);
    ys_(7)=Y_ss_v;
    ys_(8)=xc_ss_v;
    ys_(9)=xg_ss_v;
    ys_(10)=C_ss_v;
    ys_(11)=G_ss_v;
    ys_(12)=lambda_ss_v;
    ys_(13)=q_ss_v;
    ys_(14)=rk_ss_v;
    ys_(15)=w_ss_v;
    ys_(16)=mc_ss_v;
    ys_(17)=params(17);
    ys_(18)=params(17);
    ys_(19)=R_ss_v;
    ys_(20)=b_ss_v;
    ys_(21)=tr_ss_v;
    ys_(22)=taxrev_ss_v;
    ys_(23)=params(15);
    ys_(24)=params(16);
    ys_(25)=params(40);
    ys_(26)=params(44);
    ys_(27)=params(48);
    ys_(28)=params(52);
    ys_(32)=params(56);
    ys_(33)=(mc_ss_v-1)/bbc_v;
    ys_(34)=(mc_ss_v-1)/bbg_v;
    ys_(35)=1-mc_ss_v;
    ys_(39)=wtilde_ss_v;
    ys_(29)=k_tau_ss_v;
    ys_(30)=v_tau_ss_v;
    ys_(31)=div_ss_v;
    ys_(40)=C_ss_v*params(40);
    ys_(41)=params(18)*w_ss_v*params(16);
    ys_(42)=params(15)*(rk_ss_v*K_ss_v-params(60)*k_tau_ss_v-params(56)*I_ss_v);
    ys_(43)=b_ss_v*params(48)*(R_ss_v-1)/params(17);
    ys_(44)=div_ss_v*params(52);
    ys_(45)=params(44)*I_ss_v;
    ys_(46)=C_ss_v*params(40)+params(18)*w_ss_v*params(16)+params(15)*(rk_ss_v*K_ss_v-params(60)*k_tau_ss_v-params(56)*I_ss_v)+b_ss_v*params(48)*(R_ss_v-1)/params(17)+div_ss_v*params(52)-params(44)*I_ss_v;
    ys_(47)=0;
    ys_(48)=0;
    ys_(49)=0;
    ys_(50)=0;
    ys_(51)=0;
    ys_(52)=0;
    ys_(53)=0;
    ys_(54)=0;
    ys_(55)=0;
    ys_(56)=0;
    ys_(57)=0;
    ys_(60)=0;
    ys_(58)=0;
    ys_(59)=0;
    % Auxiliary equations
end
